const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (typeof $json.tender_id !== 'string' || !uuid.test($json.tender_id) || typeof $json.org_id !== 'string' || !uuid.test($json.org_id)) {
  throw new Error('INVALID_TENANT_CONTEXT');
}
return [{ json: $json }];

let data;
if ($json.pdf_texts && typeof $json.pdf_texts === 'object' && !Array.isArray($json.pdf_texts)) {
  const texts = Object.values($json.pdf_texts);
  if (!texts.length || texts.length > 1000 || texts.some(t => typeof t !== 'string') || texts.reduce((n,t) => n + t.length, 0) > 1000000) throw new Error('PDF_TEXT_LIMIT_EXCEEDED');
  const pages = [];
  for (const text of texts) {
    const marker = /\[\[SOURCE ([^\]\r\n]+) PAGE (\d+)\]\]/g;
    const matches = [...text.matchAll(marker)];
    if (!matches.length || text.slice(0, matches[0].index).trim()) throw new Error('PDF_SOURCE_REFERENCES_REQUIRED');
    for (let i=0; i<matches.length; i++) {
      const m = matches[i];
      pages.push({num:Number(m[2]), source_file:m[1], text:text.slice(m.index + m[0].length, matches[i+1]?.index ?? text.length)});
    }
  }
  data = {pages, text:texts.join('\n\n'), total:pages.length};
} else {
  const { PDFParse } = require('pdf-parse');
  const buf = Buffer.from($json.file_data, 'base64');
  const parser = new PDFParse({ data: buf });
  try { data = await parser.getText(); } finally { await parser.destroy(); }
}
const pdfText = typeof data?.text === 'string' ? data.text : '';
const pageBody = Array.isArray(data.pages) ? data.pages.map(p => p.text).join('\n') : pdfText;
const meaningfulText = pageBody.replace(/\[\[SOURCE [^\]\r\n]+ PAGE \d+\]\]/g, '').replace(/--\s*\d+\s+of\s+\d+\s*--/gi, '').replace(/^\s*Seite\s*:?\s*\d+\s*(?:von|of)\s*\d+[^\n]*$/gim, '').trim();
if (!meaningfulText) {
  console.error('PDF_TEXT_UNAVAILABLE');
  throw new Error('PDF_TEXT_UNAVAILABLE');
}
const { extractPdfPositions, extractPdfSourceMetadata } = require('tenderly-pdf-text');
const filename = String($json.file_name || $json.source_filename || 'Dokument.pdf').replace(/[\[\]\r\n]/g, '_').slice(0, 200);
const pages = (Array.isArray(data.pages) ? data.pages : [{num: 1, text: pdfText}]).map(p => ({...p, source_file: p.source_file || filename}));
const extracted = extractPdfPositions(pages);
const sourceMetadata = extractPdfSourceMetadata(pages);
const sourcedText = pages.map(p => '[[SOURCE ' + String(p.source_file || filename).replace(/[\[\]\r\n]/g, '_').slice(0,200) + ' PAGE ' + p.num + ']]\n' + p.text).join('\n\n');
if (sourceMetadata.conflicting_project_ids.length) throw new Error('MULTIPLE_TENDERS_DETECTED');
return [{ json: { ...$json, pdf_extracted: extracted, pdf_source_metadata: sourceMetadata, pdf_text: sourcedText, page_count: data.total, text_for_metadata: pdfText.substring(0, 6000), file_data: undefined } }];

const tenderId = $('trigger').first().json.tender_id;
const pdfText = $('extract-text').first().json.pdf_text;
const pageCount = $('extract-text').first().json.page_count;
const orgId = $('trigger').first().json.org_id;
const sourceFilename = $('trigger').first().json.file_name || $('trigger').first().json.source_filename || '';

const isBoundedString = (value, maxLength) =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maxLength;
const isNullableBoundedString = (value, maxLength) =>
  value === null || isBoundedString(value, maxLength);
const isValidDeadline = (value) => {
  if (value === null) return true;
  if (typeof value !== 'string') return false;
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const monthLengths = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return month >= 1 && month <= 12 && day >= 1 && day <= monthLengths[month - 1];
};

let metadata;
try {
  const aiContent = $json.choices?.[0]?.message?.content;
  if (typeof aiContent !== 'string') throw new Error('invalid response');
  const cleaned = aiContent.replace(/```json/g, '').replace(/```/g, '').trim();
  metadata = JSON.parse(cleaned);
  if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) throw new Error('invalid response');
  if (
    !isBoundedString(metadata.title, 200) ||
    !isBoundedString(metadata.summary, 2000) ||
    !isBoundedString(metadata.buyer, 500) ||
    !isNullableBoundedString(metadata.region, 300) ||
    !isValidDeadline(metadata.deadline) ||
    !isBoundedString(metadata.category, 200) ||
    !['goods', 'services', 'works', 'mixed'].includes(metadata.tender_type)
  ) throw new Error('invalid response');
} catch {
  console.error('LLM_RESPONSE_INVALID_JSON');
  throw new Error('LLM_RESPONSE_INVALID_JSON');
}

const extracted = $('extract-text').first().json.pdf_extracted || {positions: [], coverage: {status: 'unsupported', verified_complete: false}};
const source = $('extract-text').first().json.pdf_source_metadata || {};
return [{ json: {
  id: tenderId,
  org_id: orgId,
  title: metadata.title,
  buyer: metadata.buyer,
  deadline: metadata.deadline,
  summary: metadata.summary,
  region: metadata.region,
  category: metadata.category,
  tendertype: metadata.tender_type,
  source_type: 'pdf',
  gaeb_positions: extracted.positions,
  item_count: extracted.positions.filter(p => p.quantity !== null).length,
  raw_gaeb_json: [{source_type: 'pdf', pdf_extraction: extracted.coverage, source_metadata: source}],
  execution_start: source.execution_start || null,
  execution_end: source.execution_end || null,
  bindefrist_datum: source.binding_until || null,
  vergabenummer: source.project_id || null,
  source_filename: sourceFilename,
  pdf_text: pdfText,
  page_count: pageCount,
  processing_status: 'metadata_ready'
} }];
